const itens = $input.all().map(i => i.json)
  .sort((a, b) => new Date(a.enviado_em) - new Date(b.enviado_em))
  .slice(-20);

const linhas = itens.map(m => {
  let texto = m.conteudo;
  try {
    const parsed = JSON.parse(m.conteudo);
    if (Array.isArray(parsed)) texto = parsed.join(' ');
  } catch (e) {}
  const quem = m.remetente === 'cliente' ? 'Cliente' : 'Loja';
  return `${quem}: ${texto}`;
});

return [{ json: { transcript: linhas.join('\n') } }];

const orc = $('Supabase · Buscar Orçamento Aberto').first().json;

const itens = $input.all()
  .map(i => i.json)
  .filter(it => it && it.id)
  .filter(it => !String(it.descricao_livre || '').startsWith('Escola: '))
  .map(it => ({
    descricao: it.descricao_livre,
    quantidade: it.quantidade,
    valor_unitario: it.valor_unitario,
    produto_id: it.produto_id,
    precificado: it.valor_unitario !== null && it.valor_unitario !== undefined
  }));

return [{ json: { id: orc.id, protocolo: orc.protocolo, itens } }];
